changeSet.sql:
-- Tworzenie sekwencji dla tabeli INVOICE
CREATE SEQUENCE INVOICE_SEQ START WITH 1 INCREMENT BY 1;

-- Tworzenie tabeli INVOICE
CREATE TABLE INVOICE (
    INVOICE_ID BIGINT DEFAULT NEXTVAL('INVOICE_SEQ') NOT NULL,
    HOUSING_PROVIDER_ID BIGINT,
    INVOICE_NUMBER VARCHAR(100) NOT NULL,
    APARTMENT_ID BIGINT,
    MONTH DATE,
    DATE_FROM DATE,
    DATE_TO DATE,
    AMOUNT NUMERIC(10,2),
    PAY_DAY DATE,
    CONSUMPTION NUMERIC(10,2),
    METER_VALUE NUMERIC(10,2),
    PAYMENT_DATE DATE,
    PAY_DAY_MONTH DATE,
    INSERT_DATE TIMESTAMP NOT NULL,
    UPDATE_DATE TIMESTAMP,
    INSERT_OPERATOR VARCHAR(60) NOT NULL,
    UPDATE_OPERATOR VARCHAR(60),
    CONSTRAINT PK_INVOICE PRIMARY KEY (INVOICE_ID),
    CONSTRAINT FK_INVOICE_ON_HOUSING_PROVIDER FOREIGN KEY (HOUSING_PROVIDER_ID) REFERENCES HOUSING_PROVIDER(HOUSING_PROVIDER_ID),
    CONSTRAINT FK_INVOICE_ON_APARTMENT FOREIGN KEY (APARTMENT_ID) REFERENCES APARTMENT(APARTMENT_ID)
);

-- Dodanie komentarzy do tabeli i kolumn
COMMENT ON TABLE INVOICE IS 'Tabela faktur';
COMMENT ON COLUMN INVOICE.INVOICE_ID IS 'Klucz główny';
COMMENT ON COLUMN INVOICE.HOUSING_PROVIDER_ID IS 'Referencja do dostawcy świadczeń';
COMMENT ON COLUMN INVOICE.INVOICE_NUMBER IS 'Numer faktury';
COMMENT ON COLUMN INVOICE.APARTMENT_ID IS 'Referencja do apartamentu';
COMMENT ON COLUMN INVOICE.MONTH IS 'Miesiąc';
COMMENT ON COLUMN INVOICE.DATE_FROM IS 'Data od';
COMMENT ON COLUMN INVOICE.DATE_TO IS 'Data do';
COMMENT ON COLUMN INVOICE.AMOUNT IS 'Kwota';
COMMENT ON COLUMN INVOICE.PAY_DAY IS 'Termin płatności';
COMMENT ON COLUMN INVOICE.CONSUMPTION IS 'Zużycie';
COMMENT ON COLUMN INVOICE.METER_VALUE IS 'Stan licznika';
COMMENT ON COLUMN INVOICE.PAYMENT_DATE IS 'Data przelewu/zapłaty faktury';
COMMENT ON COLUMN INVOICE.PAY_DAY_MONTH IS 'Miesiąc rozliczenia';
COMMENT ON COLUMN INVOICE.INSERT_DATE IS 'Data wprowadzenia wiersza';
COMMENT ON COLUMN INVOICE.UPDATE_DATE IS 'Data aktualizacji wiersza';
COMMENT ON COLUMN INVOICE.INSERT_OPERATOR IS 'Operator wprowadzający wiersz';
COMMENT ON COLUMN INVOICE.UPDATE_OPERATOR IS 'Operator aktualizujący wiersz';
